"""A small HTTP client for talking to JSON REST APIs."""

from __future__ import annotations

from typing import Any, Mapping

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

DEFAULT_TIMEOUT = 10.0
RETRY_STATUSES = (429, 500, 502, 503, 504)


class ApiError(RuntimeError):
    """Raised when a request to the API fails."""


class ApiClient:
    """Thin wrapper around :class:`requests.Session` for JSON APIs."""

    def __init__(
        self,
        base_url: str = "",
        *,
        timeout: float = DEFAULT_TIMEOUT,
        headers: Mapping[str, str] | None = None,
        retries: int = 3,
        session: requests.Session | None = None,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = session if session is not None else self._build_session(retries)
        if headers:
            self.session.headers.update(headers)

    @staticmethod
    def _build_session(retries: int) -> requests.Session:
        session = requests.Session()
        retry = Retry(
            total=retries,
            backoff_factor=0.5,
            status_forcelist=RETRY_STATUSES,
            allowed_methods=frozenset({"GET"}),
        )
        adapter = HTTPAdapter(max_retries=retry)
        session.mount("https://", adapter)
        session.mount("http://", adapter)
        return session

    def _url(self, path: str) -> str:
        if path.startswith(("http://", "https://")):
            return path
        return f"{self.base_url}/{path.lstrip('/')}"

    def get(self, path: str, params: Mapping[str, Any] | None = None) -> Any:
        """GET ``path`` and return the decoded JSON body."""
        url = self._url(path)
        try:
            response = self.session.get(url, params=params, timeout=self.timeout)
            response.raise_for_status()
        except requests.RequestException as exc:
            raise ApiError(f"GET {url} failed: {exc}") from exc
        try:
            return response.json()
        except ValueError as exc:
            raise ApiError(f"GET {url} returned invalid JSON") from exc

    def close(self) -> None:
        self.session.close()

    def __enter__(self) -> ApiClient:
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

import pytest
import requests

from api_fetcher.client import ApiClient, ApiError


class FakeResponse:
    def __init__(self, payload=None, status_code=200, error=None):
        self._payload = payload
        self.status_code = status_code
        self._error = error

    def raise_for_status(self):
        if self._error is not None:
            raise self._error

    def json(self):
        if self._payload is _INVALID_JSON:
            raise ValueError("no json")
        return self._payload


_INVALID_JSON = object()


class FakeSession:
    def __init__(self, response):
        self.response = response
        self.headers = {}
        self.calls = []
        self.closed = False

    def get(self, url, params=None, timeout=None):
        self.calls.append({"url": url, "params": params, "timeout": timeout})
        if isinstance(self.response, Exception):
            raise self.response
        return self.response

    def close(self):
        self.closed = True


def test_get_joins_base_url_and_parses_json():
    session = FakeSession(FakeResponse({"ok": True}))
    client = ApiClient("https://api.example.com/v1", session=session)

    result = client.get("users", params={"page": 2})

    assert result == {"ok": True}
    assert session.calls[0]["url"] == "https://api.example.com/v1/users"
    assert session.calls[0]["params"] == {"page": 2}


def test_get_uses_absolute_url_as_is():
    session = FakeSession(FakeResponse([]))
    client = ApiClient("https://api.example.com", session=session)

    client.get("http://other.example.com/items")

    assert session.calls[0]["url"] == "http://other.example.com/items"


def test_get_wraps_request_errors():
    session = FakeSession(requests.ConnectionError("boom"))
    client = ApiClient("https://api.example.com", session=session)

    with pytest.raises(ApiError, match="failed"):
        client.get("users")


def test_get_wraps_http_error_status():
    error = requests.HTTPError("404 Client Error")
    session = FakeSession(FakeResponse(status_code=404, error=error))
    client = ApiClient("https://api.example.com", session=session)

    with pytest.raises(ApiError):
        client.get("missing")


def test_get_wraps_invalid_json():
    session = FakeSession(FakeResponse(_INVALID_JSON))
    client = ApiClient("https://api.example.com", session=session)

    with pytest.raises(ApiError, match="invalid JSON"):
        client.get("broken")


def test_context_manager_closes_session():
    session = FakeSession(FakeResponse({}))
    with ApiClient("https://api.example.com", session=session) as client:
        assert isinstance(client, ApiClient)

    assert session.closed is True

import json

import pytest

from api_fetcher.__main__ import _parse_params, main


def test_parse_params():
    assert _parse_params(["a=1", "b=two"]) == {"a": "1", "b": "two"}


def test_parse_params_rejects_missing_equals():
    with pytest.raises(Exception):
        _parse_params(["broken"])


def test_main_prints_json(monkeypatch, capsys):
    class StubClient:
        def __init__(self, *args, **kwargs):
            pass

        def __enter__(self):
            return self

        def __exit__(self, *exc):
            return False

        def get(self, url, params=None):
            return {"url": url, "params": params}

    monkeypatch.setattr("api_fetcher.__main__.ApiClient", StubClient)

    exit_code = main(["https://api.example.com/users", "-p", "page=2"])

    assert exit_code == 0
    assert json.loads(capsys.readouterr().out) == {
        "url": "https://api.example.com/users",
        "params": {"page": "2"},
    }


def test_main_reports_api_errors(monkeypatch, capsys):
    from api_fetcher.client import ApiError

    class StubClient:
        def __init__(self, *args, **kwargs):
            pass

        def __enter__(self):
            return self

        def __exit__(self, *exc):
            return False

        def get(self, url, params=None):
            raise ApiError("nope")

    monkeypatch.setattr("api_fetcher.__main__.ApiClient", StubClient)

    exit_code = main(["https://api.example.com/users"])

    assert exit_code == 1
    assert "nope" in capsys.readouterr().err

